<script setup lang="ts">
const props=defineProps<{game:any;targetType:string;targetId:string}>(),emit=defineEmits(['changed','processing'])
const data=ref<any>(null),error=ref(''),busy=ref(false),review=ref(''),history=ref<any[]>([]),offset=ref(0),expanded=ref(false)
const labels:any={stability:'Estabilidade',security:'Segurança',economy:'Economia',tension:'Tensão',difficulty:'Dificuldade',risk:'Risco'},levels=['Desconhecido','Preliminar','Verificado','Detalhado']
const commandStore=useState<Record<string,any>>('intelligence-commands',()=>({})),pending=computed({get:()=>commandStore.value[props.game.id]??null,set:(v:any)=>commandStore.value={...commandStore.value,[props.game.id]:v}}),locked=computed(()=>busy.value||!!pending.value)
const base=()=>'/api/v1/games/'+props.game.id+'/intelligence',query=()=>'?targetType='+props.targetType+'&targetId='+encodeURIComponent(props.targetId)
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'USD'}).format(n/100)
let refreshSerial=0
async function refresh(){const serial=++refreshSerial,scope=base()+query();try{const next=await $fetch<any>(scope+'&limit=10');if(serial!==refreshSerial||scope!==base()+query())return false;data.value=next;history.value=data.value.history;offset.value=history.value.length;return true}catch(e:any){if(serial!==refreshSerial||scope!==base()+query())return false;error.value=e.data?.message||'Não foi possível carregar a inteligência.';return false}}
async function more(){try{const page=await $fetch<any>(base()+query()+'&limit=10&offset='+offset.value);history.value.push(...page.history);offset.value+=page.history.length;data.value.pagination=page.pagination}catch{error.value='Não foi possível carregar o histórico.'}}
async function run(){if(busy.value||(!review.value&&!pending.value))return;const command=pending.value||{requestId:crypto.randomUUID(),expectedVersion:data.value.stateVersion,targetType:props.targetType,targetId:props.targetId,topic:review.value};pending.value=command;busy.value=true;emit('processing',true);error.value='';let done=false;try{await $fetch(base()+'/analyses',{method:'POST',body:command});if(!await refresh())return;pending.value=null;review.value='';done=true}catch(e:any){if(e.status>=400&&e.status<500){pending.value=null;review.value='';await refresh()}error.value=e.data?.message||'Falha de conexão. Repita para recuperar a mesma análise.'}finally{busy.value=false;emit('processing',!!pending.value)}if(done)emit('changed')}
watch(()=>[props.game.id,props.game.stateVersion,props.targetType,props.targetId],async()=>{review.value='';data.value=null;await refresh()})
onMounted(async()=>{emit('processing',!!pending.value);await refresh()})
</script>
<template><section class="intel-panel"><div class="panel-heading"><h3>Inteligência da companhia</h3><span class="tag">ESTIMATIVAS</span></div><p>Novas fontes podem divergir. Confiança diminui com a idade; comprar informação não reduz o risco real.</p><div v-if="error" class="error" role="alert">{{error}}</div>
 <div v-if="pending&&!busy" class="panel"><p>Análise aguardando confirmação. Repetir mantém o mesmo pedido e débito.</p><button class="primary" @click="run">Repetir solicitação</button></div>
 <template v-if="data"><article v-for="t in data.topics" :key="t.topic" class="intel-topic"><div class="panel-heading"><strong>{{labels[t.topic]}} · {{levels[t.level]}}</strong><span v-if="t.conflicting" class="tag">FONTES CONFLITANTES</span><span v-else-if="t.stale" class="tag">OBSOLETA</span></div><p v-if="t.estimate">Intervalo {{t.estimate.min}}–{{t.estimate.max}} / 100 · confiança atual {{t.confidence}}%<br>{{t.sourceName}} · coleta T{{t.collectedTurn}} · válida até T{{t.validUntilTurn}} · idade {{t.age}} turno(s)</p><p v-else>Sem conhecimento vigente. O histórico pode conter estimativas antigas.</p>
 <details v-if="t.sources.length"><summary>Comparar {{t.sources.length}} fonte(s)</summary><p v-for="s in t.sources" :key="s.id">{{s.sourceName}} · {{s.estimate.min}}–{{s.estimate.max}} · nível {{s.collectedLevel}} na coleta<br>Confiança {{s.collectedConfidence}}% → {{s.confidence}}% · T{{s.collectedTurn}} → T{{s.validUntilTurn}}<span v-if="s.stale"> · obsoleta</span></p></details>
 <button class="secondary" :disabled="locked||game.cashCents<data.analysis.costCents||data.analyses.some((j:any)=>j.topic===t.topic&&j.status==='pending')" @click="review=t.topic">Analisar {{labels[t.topic].toLowerCase()}} · {{money(data.analysis.costCents)}}</button></article>
 <section v-if="review" class="panel decision-card"><h3>Solicitar análise de {{labels[review].toLowerCase()}}?</h3><p>Cobrança ao passar o turno: {{money(data.analysis.costCents)}}. Prazo: {{data.analysis.turns}} turnos. Duas análises simultâneas por companhia. Não há reembolso automático; o relatório pode divergir de outras fontes.</p><div class="personnel-actions"><button class="primary" :disabled="locked" @click="run">Agendar análise</button><button class="secondary" :disabled="locked" @click="review=''">Voltar</button></div></section>
 <p v-for="j in data.analyses.filter((j:any)=>j.status==='pending')" :key="j.id" role="status">Análise de {{labels[j.topic].toLowerCase()}} em andamento · entrega T{{j.dueTurn}}.</p>
 <button class="secondary" @click="expanded=!expanded">{{expanded?'Ocultar histórico':'Histórico de conhecimento'}}</button><div v-if="expanded"><article v-for="r in history" :key="r.id" class="mission-report"><span class="eyebrow">{{labels[r.topic]}} · {{r.sourceName}}</span><p>{{r.estimate.min}}–{{r.estimate.max}} · {{levels[r.collectedLevel]}} na coleta<br>T{{r.collectedTurn}} · válida até T{{r.validUntilTurn}} · confiança atual {{r.confidence}}%<span v-if="r.stale"> · obsoleta</span><br><span v-if="r.supersedesId">Atualiza registro anterior desta fonte.</span></p></article><button v-if="data.pagination.hasMore" class="secondary" @click="more">Carregar mais registros</button></div>
 </template><p v-else>Carregando conhecimento…</p></section></template>
